	title 'QD RgnDefs           GS ROM 2.0'*****************************************************************			   **	   RgnDefs		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1986-1987	   **	All Rights Reserved		   **	Apple Computer, Inc.	   *** Modification history:** Feb 7, 1989 	Konstantin and Dave**	Speed up point in region call.*** Feb 13, 1989 	Konstantin and Dave**	Fixed bug in PtInRgn** March 7, 1989	Konstantin**	Made XorScan call shorter and faster.*****************************************************************	string asis	blanks off			include 'all.macros'	MACRO&lab	MoveL &Label1,&Label2&lab	lda &Label1	sta &Label2	lda &Label1+2	sta &Label2+2	MEND	MACRO&lab	MoveP &Label1,&Label2&lab	lda &Label1,s	sta &Label2	lda &Label1+2,s	sta &Label2+2	MEND	MACRO&lab	PushNil&lab	lda #0	pha	pha	MEND	MACRO&lab	IncYWd&lab	iny	iny	MEND	MACRO&lab	DecYWd&lab	dey	dey	MEND	MACRO&lab	IncYPtr&lab	iny	iny	iny	iny	MEND	MACRO&lab	DecYPtr&lab	dey	dey	dey	dey	MEND	MACRO&lab	MoveLong &From,&To&lab	lda &From	sta &To	lda &From+2	sta &To+2	MEND	include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:core.globals1'	INCLUDE ':QDEquates:core.globals2'	INCLUDE ':QDEquates:region.equs'	INCLUDE ':QDEquates:rect.equs'	INCLUDE ':QDEquates:rgndefs.equs';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT BusyEC0	IMPORT BusyEC12	IMPORT BusyEC4	IMPORT BusyEC8	IMPORT BusyErr0	IMPORT BusyErr12	IMPORT BusyErr4	IMPORT BusyErr8	IMPORT DerefA	IMPORT DerefB	IMPORT DerefHandle	IMPORT GetNewHandle	IMPORT QDStart	IMPORT ReSizeHandle	IMPORT UnlockA	IMPORT UnlockHandle;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY DiffScan	ENTRY DoRgnOp	ENTRY InsetScan	ENTRY LocalMapPoint	ENTRY MapAndScale	ENTRY RetrieveRects	ENTRY RgnSector	ENTRY SectScan	ENTRY UnionScan	ENTRY XorScan;                copy rgndefs/ptinrgn****************************************************************** Function PtInRgn*****************************************************************	EXPORT PtInRgnPtInRgn	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Rgn	equ RTL2+3PointPtr	equ Rgn+4Result	equ PointPtr+4	jsr QDStart	lda  #0		;zero out the result and the X-Reg	tax		;..(this is the internal result)	sta  Result,s	lda  PointPtr,s		;get the point to test into zero	sta  Temp		;..page (H,V)	lda  PointPtr+2,s	sta  Temp+2	ldy  #2	lda  [Temp]	sta  V	lda  [Temp],y	sta  H	lda  Rgn+2,s		;Temp = our region handle	sta  Temp+2	lda  Rgn,s	sta  Temp	lda  [Temp],y		;deref the handle using the fact	sta  BufPtr+2		;..that Y-Reg is already two	lda  [Temp]	sta  BufPtr	lda  V		;Y-Reg is already two here	cmp  [BufPtr],y	bmi  allDone	ldy  #6	cmp  [BufPtr],y	bpl  allDone	lda  H	ldy  #4	cmp  [BufPtr],y	bmi  allDone	ldy  #8	cmp  [BufPtr],y	bpl  allDone	lda  #10	cmp  [BufPtr]	beq  isInTheRgn;---------------------------------------------------------------nextVert	iny		;this looks in the region for the point	iny	lda  V	cmp  [BufPtr],y	bmi  done	lda  HnextHor	iny	iny	cmp  [BufPtr],y	bmi  lookForEnddoToggle	inx	bra  nextHorlookForEnd	lda  [BufPtr],y	cmp  #MaxInt	beq  nextVert	iny	iny	bra  lookForEnd;---------------------------------------------------------------done	txa	lsr  a	bcc  allDoneisInTheRgn	lda  #$FFFF	sta  Result,sallDone	jmp  BusyEC8;---------------------------------------------------------------	ENDP****************************************************************** Function RectInRgn** Change History** March 10, 1987  Steven Glass** A case that was not working right showed a place where* register was being trashed.  This is working below.** Change History* 7/23/87      GCP	   replaced BufPtr with BufHandle. We were*	   looking in the wrong place before disposing*	   of the handle*****************************************************************	EXPORT RectInRgnRectInRgn	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Rgn	equ RTL2+3RectPtr	equ Rgn+4Result	equ RectPtr+4RgnFlag	equ PtCount+2	jsr QDStart	lda #0	; init result to false	sta Result,s	sta BufHandle	; init handle to nil	sta BufHandle+2	lda Rgn,s	; pull Rgn handle off the stack	sta RgnHandleA	lda Rgn+2,s	sta RgnHandleA+2	ldx #RgnHandleA	; set up dereference pointer	jsr DerefHandle	; dereference and lock it	sta RgnPtrA	stx RgnPtrA+2	lda RectPtr,s	; get rectangle off	stack	sec	sbc #2	; fake out RgnSector (make it think	sta RgnPtrB	; it really has a region by subtracting	lda RectPtr+2,s	; two from the pointer)	sbc #0	sta RgnPtrB+2	jsr RgnSector	lda RgnY1	cmp RgnY2	bpl GoHome	lda RgnX1	cmp RgnX2	bpl GoHome	lda [RgnPtrA]	cmp #10	bne NotYet	brl ItsInThereGoHome	brl NotInThereNotYet	sec	lda RgnX2	sbc RgnX1	clc	adc #$000F	; past next full word	lsr A	; divide by 8	lsr A	lsr A	and #$FFFE	; even number of words	sta PtCount	; tuck it away	ldx #BufHandle	; offset to handle location	jsr GetNewHandle	; utility routine to get/deref handle	bcc NoError	pha	; save error	ldx #RgnHandleA	jsr UnlockHandle	plx	; retrieve error	jmp BusyErr8NoError	sta BufPtr	stx BufPtr+2	ldy PtCount	; get count	DecYWd	lda #0ClearLoop	sta [BufPtr],y	DecYWd	bpl ClearLoop	stz RgnFlag	; init our toggle to off	ldy #10NxtVert	lda RgnY1	cmp [RgnPtrA],y	; set flags on Y1-Rgn.Y	bmi FastTrack	IncYWdNxtHoriz	lda [RgnPtrA],y	IncYWd	cmp #MaxInt	beq NxtVert	cmp RgnX2	; is it too far?	bpl NxtHoriz	; yes, ignore it* It was somewhere left of the right edge of our rect.  We must toggle* our inversion flag.	pha	; save point (added	10 Mar 87-SEG)	lda RgnFlag	eor #$FFFF	sta RgnFlag	pla	; get point back (added 10 mar 87)	cmp RgnX1	bmi NxtHoriz* Now we have an inversion point that falls within X1 <= X < X2	phy	; save y	sec	sbc RgnX1	; normalize it	sta Temp	and #$000F	; mod 16	asl A	; make it a byte offset	tax	lda >Mask,x	sta Temp+2	lda Temp	lsr A	; find the byte the	point is in	lsr A	lsr A	and #$FFFE	; align it to a word boundary	tay	; index it	lda [BufPtr],y	; get what it is now	eor Temp+2	; toggle the bit	sta [BufPtr],y	; put it back	ply	bra NxtHorizMask	DC.W $8000,$4000,$2000,$1000	DC.W $0800,$0400,$0200,$0100	DC.W $0080,$0040,$0020,$0010	DC.W $0008,$0004,$0002,$0001* When we get to the FastTrack, we are guaranteed to be past the first* scan line of the rectangle, so any inversion point which falls within* the horizontal limits X1 <= X < X2 means we've found a hit.  First,* check for hits up	to this point.  If there aren't any, keep scanning* until we pass Y2 or find one.FastTrack	lda RgnFlag	bne ItsInThere	sty Temp	ldy PtCount	DecYWdTestLoop	lda [BufPtr],y	bne ItsInThere	DecYWd	bpl TestLoop	ldy TempNxtVert2	lda [RgnPtrA],y	IncYWd	cmp RgnY2	; set flags on Rgn.Y-RgnY2	bpl NotInThereNxtHoriz2	lda [RgnPtrA],y	IncYWd	cmp #MaxInt	beq NxtVert2	cmp RgnX1	bpl NoToggle	lda RgnFlag	eor #$FFFF	sta RgnFlag	bra NxtHoriz2NoToggle	cmp RgnX2	bmi ItsInThere	lda RgnFlag	; if the rgn flag is on, we've got one	bne ItsInThere* It wasn't in there, so advance us to the end of scan markerSkipThisOne	lda [RgnPtrA],y	IncYWd	cmp #MaxInt	bne SkipThisOne	bra NxtVert2ItsInThere	lda #1	sta Result,sNotInThere	ldx #RgnHandleA	jsr UnlockHandle	lda BufHandle	ora BufHandle+2	beq NoHandle	ldx #BufHandle	jsr UnlockHandle	PushLong BufHandle	_DisposeHandle	bcs ErrNoHandle	jmp BusyEC8Err	jmp BusyErr8	ENDP;                copy rgndefs/rgnsave****************************************************************** RgnSave** Internal routine to determine if we are save in the process* of defining a region.** 3/9/89	Mensch* Modify the dirty flags at the proper times****************************************************************	EXPORT RgnSaveRgnSave	PROC*              using coredata	ldy #o_RgnSave	lda [PortRef],y	sta BufHandle	iny	iny	lda [PortRef],y	sta BufHandle+2	ora BufHandle	beq IsZeroNotZero	sec	rtsIsZero	phx	ldx #512	lda <DirtyDPFlags,x	ora #NoRgnRecord+NoPolyRecord	sta <DirtyDPFlags,x	plx	lda #0	clc	rts	ENDP;                copy rgndefs/putrect****************************************************************** Procedure AddPt2Rgn;**   A point is passed in registers, the	x value in the x register*   and the y value	in the A register.	These are added to the*   inversion point	list and y is incremented.  No other registers*   are changed.*****************************************************************	EXPORT AddPt2RgnAddPt2Rgn	PROC	sta [BufPtr],y	; store y value	iny	; increment y	iny	; increment y	txa	; get x value	sta [BufPtr],y	; store x value	iny	; increment y	iny	; increment y	rts	; get outa here	ENDP****************************************************************** Procedure PutRect(r:rect; bufHandle:Handle; var Index,Size:integer);**   Puts the four inversion points of a	rectangle.**   This being an internal routine, the	rectangle is stored	on zero*   page in Y1,X1,Y2,X2.  bufHandle is a handle to a list of inversion*   points and has been placed in RgnHandleC.  The first two bytes of*   the list are the maximum size.  The	second two bytes are the*   current size.  We will bump the handle by 1024 bytes if	we*   don't have enough room for 16 more bytes (4 points), then add the*   four points onto the end.  Note that the number of points is*   (index div 4) -	1*****************************************************************	EXPORT iPutRectiPutRect	PROC*              using ErrorDataOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3* avoid locking/derefing once the caller does it properly	ldx #BufHandle	jsr DerefHandle	; dereference the current handle	sta BufPtr	; save pointer returned in A & X	stx BufPtr+2	ldy #2	; current index offset	lda [BufPtr],y	; get index	pha	; save it	clc	; prepare for add	adc #16	; room we need for 4 points	sta [BufPtr],y	; store it while we	have it	cmp [BufPtr]	; set flags on index - size	bcc SizeOk	; blt SizeOk	beq SizeOk	; ble SizeOk	lda [BufPtr]	; get current maximum	clc	; clear carry for adc* We generally won't be calling too many rectangles in a row, so bump* the size just by a page.	adc #256	; bump size by 256	bcs BufferOverflow	; if we wrapped, we	quit	ldx #BufHandle	; point X at BufHandle	jsr ReSizeHandle	; resize, relock, rederef	bcs ErrorOut	; if we failed, propogate the error	sta BufPtr	; save pointer	stx BufPtr+2SizeOk	ply	; reload y	ldx x1	; get left	lda y1	; get top	jsr AddPt2Rgn	; put point	ldx x2	; get right	lda y1	; get top	jsr AddPt2Rgn	; put point	ldx x1	; get left	lda y2	; get bottom	jsr AddPt2Rgn	; put point	ldx x2	; get right	lda y2	; get bottom	jsr AddPt2Rgn	; put point* avoid unlocking once the caller does it	ldx #BufHandle	; unlock the buffer	handle	jsr UnlockHandle	clc	rtlBufferOverflow	lda #RgnFull	; error to say we had troublesErrorOut	pha	; save error code	ldx #BufHandle	; unlock the buffer	handle	jsr UnlockHandle	pla	; restore error code	sec	; restore error flag	rtl	; get outa here	ENDP;                copy rgndefs/putline****************************************************************** Procedure PutLine(pt1,pt2:Point; dst:Handle; var index,bufmax:integer);**   Puts inversion points for a line segment.**   This being an internal routine, the	points are stored on zero*   page in Y1,X1,Y2,X2.  bufHandle is a handle to a list of inversion*   points.  The first two bytes of the	list are the maximum size.*   The second two bytes are the current size.*****************************************************************	EXPORT iPutLineiPutLine	PROC*              using ErrorDataOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3* We assume in Putline that BufHandle is already dereferenced and locked* down for us.  This should make life easier for the polygon routines, so* that the dereferencing and locking need only be done once	or in the* event of a resizing.* avoid locking/derefing once the caller does it	ldx #BufHandle	; get the inversion	point buffer	jsr DerefHandle	; dereference it	sta BufPtr	; save pointer returned in A & X	stx BufPtr+2	ldy #2	; current index offset	lda [BufPtr],y	; get index	sta Index	; keep track of it* If line is vertical, ignore it since it must already connect to* existing horizontal lines.	sec	; set for subtract	lda X2	; we'll subtract so we have the	sbc X1	; result in case we	need it	bne NotVertical	jmp Exit	; jump out all the wayNotVertical	sta DeltaX	; save this for later* Calculate bytes needed as 8 * (Min(abs(dh),abs(dv))+1)	bpl DhPos	eor #$FFFF	inaDhPos	sta Temp	; switch to using RgnY1..RgnX2	lda Y1	sta RgnY1	lda X1	sta RgnX1	lda Y2	sta RgnY2	lda X2	sta RgnX2	sec	lda RgnY2	sbc RgnY1	sta DeltaY	bpl DvPos	eor #$FFFF	inaDvPos	cmp Temp	bmi DvLess	lda TempDvLess	ina	; bump by 1** Addition by SEG (20 May 86) to return	error* on overflow*	cmp #$2000	; check this number	to see if it is too	bcs BufferOverflow	; big to handle and	quit if yes** End addition.*	asl A	; now mult by 8	asl A	asl A	clc	adc Index	bcs BufferOverflow	; if we wrapped, we	quit	cmp [BufPtr]	bcc NoGrow	beq NoGrow	ldx #BufHandle	; get offset to handle	jsr ResizeHandle	; resize it	bcc SavePtr	bra ErrorOutBufferOverflow	lda #RgnFull	; error to say we had troublesErrorOut	pha	; save error code	ldx #BufHandle	; unlock the buffer	handle	jsr UnlockHandle	pla	; restore error code	sec	; restore error flag	rtl	; get outa hereSavePtr	sta BufPtr	; save pointer	stx BufPtr+2NoGrow	lda RgnY1	cmp RgnY2	bne Slanted	lda RgnY1	ldx RgnX1	ldy Index	; AddPt2Rgn updates	y	jsr AddPt2Rgn	lda RgnY2	ldx RgnX2	jsr AddPt2Rgn	jmp Done	; go fix up the lengthSlanted	bmi NoSwap	; if Y1-Y2 < 0, don't swap	ldx RgnY2	; A already has Y1	sta RgnY2	stx RgnY1	lda RgnX1	; swap horizontals to match	ldx RgnX2	sta RgnX2	; we don't need to swap deltas	stx RgnX1	; because the sign changes cancelNoSwap	lda RgnY1	sta V	; init V to top V	pea 0	; room for result	pea 0	pei DeltaX	; sure glad we caught these earlier	pei DeltaY	_FixRatio	; get the ratio	pla	sta Slope	; hmmm - zero page already ?	pla	sta Slope+2	lda RgnX1	sta Horiz+2	; Horiz.Int := top horiz	lda #$8000	sta Horiz	; Horiz.Fract := 1/2* Adjust horiz depending on sign and magnitude of slope* Horiz := Horiz + Slope/2	lda Slope+2	; is slope negative	asl A	; get sign of slope	lda Slope+2	; get high word of slope back	ror A	; divide by 2, preserving sign	sta Temp	; save the high word	lda Slope	ror A	; A has low word of	slope/2	clc	adc Horiz	; add into Horiz	sta Horiz	; and save it	lda Temp	; get the high word	back	adc Horiz+2	; add using carry	sta Horiz+2	; and save it	lda Slope+2	; is slope negative?	bmi NegSlope	; yes, continue	bne SlopeOk	; if high word >0, then slope >= 1* Add slope to LeftEdge	clc	lda Slope	; get low word	adc Horiz	; add low word of Horiz	sta Horiz	; save it	lda Slope+2	; get high word of slope	adc Horiz+2	; add high word of Horiz with carry	sta Horiz+2	; save high word	bra SlopeOk	; and continueNegSlope	eor #$FFFF	; is slope >= FFFF0000	beq SlopeOk	inc Horiz+2	; add 1 to horizSlopeOk		; * For Vert := TopV to BotV-1 add slope to Horiz and put slabs	lda RgnX1	sta H	ldy IndexLoop	lda H	cmp Horiz+2	beq NoChng	lda V	; get current V	sta [BufPtr],y	; put it	IncYWd	lda H	; get old H	sta [BufPtr],y	; put it	IncYWd	lda V	; get V again	sta [BufPtr],y	; put it	IncYWd	lda Horiz+2	; get new H	sta [BufPtr],y	; put it	sta H	; update H	IncYWdNoChng	inc V	; bump V	clc	lda Slope	adc Horiz	sta Horiz	lda Slope+2	adc Horiz+2	sta Horiz+2	lda V	cmp RgnY2	bne Loop* Finish up last slab	lda H	cmp RgnX2	beq Done	lda V	sta [BufPtr],y	IncYWd	lda H	sta [BufPtr],y	IncYWd	lda V	sta [BufPtr],y	IncYWd	lda RgnX2	sta [BufPtr],y	IncYWdDone	tya	ldy #2	sta [BufPtr],y	lsr A	; divide by 4	lsr A	dea	sta PtCount	; be a good neighbor* avoid unlocking once the caller does itExit	ldx #BufHandle	; set up offset	jsr UnlockHandle	; get rid of this when okay	clc	rtl	ENDP;                copy rgndefs/putrgn******************************************************************* Procedure PutRgn**   Input is a RgnHandle in RgnHandleA and buffer in BufHandle.*   The buffer size	is held in the first two bytes of BufHandle's*   data, and the index (offset to the end of the buffer) in*   bytes 2-3 of the same.  PutRgn expands a region out to an*   array of inversion points, and thus	functions as the inverse*   of PackRgn.  The caller should unlock RgnHandleA after use.*****************************************************************	EXPORT iPutRgniPutRgn	PROC*              using ErrorData* delete the next eight lines once BufHandle is set up correctly	ldx #BufHandle	; dereference and lock BufHandle	jsr DerefHandle	sta BufPtr	; save pointer	stx BufPtr+2	ldx #RgnHandleA	; dereference and lock RgnHandleA	jsr DerefHandle	sta RgnPtrA	; save pointer returned in A & X	stx RgnPtrA+2	ldy #2	; offset to current	index	lda [BufPtr],y	; get buffer length	sta Index	; save index	lda [RgnPtrA]	; get region size	asl A	; times 2	clc	; prepare for add	adc Index	; what we'll need	cmp [RgnPtrA]	; set flags on needed-current	bcc NoGrow	; if current > needed, ok	beq NoGrow	; or even this way	adc #256	; bump our size for	some sluff	bcs BufferOverflow	; if we wrapped, we	report an error	ldx #BufHandle	; offset to the handle to resize	jsr ResizeHandle	; resize BufHandle	bcc SavePtr	bra ErrorOutBufferOverflow	lda #RgnFull	; error to say we had troublesErrorOut	pha	; save error code	ldx #BufHandle	; unlock the buffer	handle	jsr UnlockHandle	pla	; restore error code	sec	; restore error flag	rtl	; get outa hereSavePtr	sta BufPtr	; save pointer	stx BufPtr+2NoGrow	lda #10	; size of a rectangular region	cmp [RgnPtrA]	; is region rectangular	bne NotRect	; no, continue* Use the bounding box to insert 4 points (Top,Left), (Top,Right),* (Bottom,Left), and (Bottom,Right).	ldy #8	; offset to right	lda [RgnPtrA],y	; get right	pha	; push it	ldy #6	; offset to bottom	lda [RgnPtrA],y	; get bottom	pha	; push it	ldy #4	; offset to left	lda [RgnPtrA],y	; get left	pha	; push it	ldy #2	; offset to top	lda [RgnPtrA],y	; get top	ldy Index	; destination for next point	tax	; save top in x	sta [BufPtr],y	; save top	IncYWd	lda 1,s	; get left	sta [BufPtr],y	; save it	IncYWd	txa	; get top	sta [BufPtr],y	; save top again	IncYWd	lda 5,s	; get right	sta [BufPtr],y	; save right	IncYWd	lda 3,s	; get bottom	tax	; save it in x	sta [BufPtr],y	; save bottom	IncYWd	pla	; get left	sta [BufPtr],y	; save it	IncYWd	; bump y	pla	; get bottom	sta [BufPtr],y	; save it	IncYWd	; bump y	pla	; get right	sta [BufPtr],y	; save it	IncYWd	; bump y	tya	; transfer indexDone	ldy #2	; offset to index	sta [BufPtr],y	; save index	lsr A	lsr A	dea	sta PtCount	; be a good neighbor	ldx #BufHandle	jsr UnlockHandle	clc	; no error	rtlCleanup	lda Index	; get current offset	bra Done	; share codeNotRect	ldy #10	; offset to first vertNxtVert	lda [RgnPtrA],y	; get next vert	cmp #MaxInt	; is it MaxInt	beq Cleanup	; if so, clean up and quit	sta Temp	; stow it	IncYWd	; bump yNextHor	lda [RgnPtrA],y	; get next horizontal	IncYWd	; bump y	cmp #MaxInt	; is it Maxint?	beq NxtVert	; if so, check vertical	tax	; stow it	lda [RgnPtrA],y	; get second horizontal	sta Temp+2	; save it	IncYWd	; bump y	sty SrcY	; save offset pointer	ldy Index	; get index	lda Temp	; get vert back	sta [BufPtr],y	; put vert	IncYWd	; bump y	txa	; get horizontal back	sta [BufPtr],y	; put horizontal	IncYWd	; bump y	lda Temp	; get vert back	sta [BufPtr],y	; put vert	IncYWd	; bump y	lda Temp+2	; get second horizontal	sta [BufPtr],y	; put second horizontal	IncYWd	; bump y	sty Index	; save it	ldy SrcY	; get source index	bra NextHor	; look for more horizontal values	ENDP;                copy rgndefs/cullpoints****************************************************************** Procedure CullPoints; internal;**   BufHandle is a pointer to a list of	inversion points.  The*   zero page variable PtCount tells us	how many there are*   at the moment.	Remove any duplicate points (which cancel*   each other) and	update PtCount if necessary.*****************************************************************	EXPORT iCullPointsiCullPoints	PROC* The buffer is stored in BufHandle and	is already dereferenced* into BufPtr and is locked down.	ldx PtCount	; how many points to do?	beq DnCull	; if 0, well, that was easy	ldy #4	lda [BufPtr],y	; set up the first points	sta PointV	; save it	ldy #6	; point y a h	lda [BufPtr],y	; set up PointH	sta PointH	; save it	ldy #8	; initial NextY value	sty NextY	; save it	stz Sluff	; sluff := false	bra More	; let's do itDnCull	rtl	; get outa hereCheckStarted	lda Sluff	bne ToEndCull* Only the last two	points need to be culled.  Set up DestY	so* we can share common end code.	sec	lda NextY	sbc #8	sta DestYToEndCull	brl EndCull	; help out short branch* We get to Delete knowing it is time to delete a point.  We have* to restore our environment to something sensible.  First,	we* decrement x twice.  If it's 0, we're done.  If not, we update* NextY, PointV, and PointH.  Then if x=1 we jump ahead to LastPt.* Y comes in equal to NextYDelete	dex	; kill first point	dex	; kill with second point	beq CheckStarted	; go do EndCull via	ToEndCull* at this point, y is pointing at H of NextY.  We must push	it* onwards by 6 bytes, and we know we can because the x register is* not yet exhausted.  However, along the way we can use it to get* the values of the	current PointV,PointH.	lda Sluff	; check our flag	bne Started	; if <> 0, we've deleted something	inc Sluff	; Sluff now <> 0	lda NextY	; DestY := NextY-4	sec	; for subtract	sbc #8	; decrement by 8	sta DestY	; save correct valueStarted	lda [BufPtr],y	; get PointV	sta PointV	; save it	IncYWd	; bump y by 2 to H offset	lda [BufPtr],y	; get PointH	sta PointH	; save it	IncYWd	; bump y by 2 to V offset	sty NextY	; save it in case x=1	cpx #1	; is x=1?	beq SetupLastPt	; go do lastpoint* When we get to More, we have the current point stored in PointV and* PointH.  The y register points at the	next entry.More	ldy NextY	; look at next point	lda [BufPtr],y	; get next point v	sta Temp	; save it	IncYWd	; bump to horizontal	lda [BufPtr],y	; fetch it	sta Temp+2	; save it	IncYWd	; bump Y to next point	sty NextY	; save pointer	cmp PointH	; do horizontal first since A is set	bne HDiff	; if <>, save A and	continue	lda Temp	cmp PointV	beq Delete	; kill these pointsHDiff	lda Sluff	; are we copying yet	beq NoCopy	; nope, not yet* copy the old point back down	ldy DestY	; get the next dest	lda PointV	; get V	sta [BufPtr],y	; store it	IncYWd	; bump y by 2	lda PointH	; get H	sta [BufPtr],y	; store it	IncYWd	; bump y by 2	sty DestY	; save itNoCopy	dex	; done with 1 point	(or maybe two)	beq EndCull	; tidy up if x=0	cpx #1	; is x=1?	beq DoLastPt	; go do lastpoint* we got here from the normal loop, so Temp contains the next point to* use in the comparisons.  Copy it into	PointV,PointH and start the loop.	lda Temp	; get next V	sta PointV	; save it	lda Temp+2	; get next H	sta PointH	; save that too	bra More	; start the loop againSetupLastPt	lda PointV	; we gonna use temp	below	sta Temp	lda PointH	sta Temp+2DoLastPt	lda Sluff	; check our flag	beq Nochange	; if nothing deleted by now, just leave	lda Temp	; these should be set	ldy DestY	; get destination offset	sta [BufPtr],y	; save it	lda Temp+2	; next value	IncYWd	; bump y by 2	sta [BufPtr],y	; save it	IncYWd	; for good measure	sty DestY	; save itEndCull	lda DestY	; points at next location	lsr A	; divide by 2	lsr A	; divided by 4	dea	; -1 for start	sta PtCount	; updated PtCountNoChange	rtl	ENDP;                copy rgndefs/sortpoints****************************************************************** Procedure SortPoints**   Upon entering SortPoints, the list of inversion points to*   be QuickSorted is found in RgnHandleA and RgnPtrA on zero*   page.  The number of points is found in PtCount, also on*   zero page.  This routine performs a	QuickSort on the list*   and uses log (base 2) n of stack space.  Since the list	is*   constrained to fit in one 64K bank (to accomodate the range*   of the y register) we will need a maximum of log (base 2) 16K,*   or 14, times the stack space per partition element (4 bytes)*   or about 56 bytes.*****************************************************************	EXPORT iSortPointsiSortPoints	PROC* The buffer is stored in BufHandle and	is already dereferenced and* locked down.	ldy #4	; start of list	sty lptr	; save this ptr	ldx #1	; we'll put one entry on the stack	stx SpCount	; one item on our stack	tya	; stack[1].l := 1	pha	; push it	lda PtCount	; stack[1].r := PtCount	asl A	; multiply by 2	asl A	; multiply by 4 (includes -4 offset)	pha	; push it* repeat { pop top request from stack }* ..lptr := a[s].l;	rptr := a[s].rPopNext	pla	; pop right	sta rptr	; new zero page	pla	; pop left	sta lptr	; new zero page	dec SpCount	; decrement stack count* ..repeat { split a[l] ... a[r] }* ....iptr := lptr;	j := rptr; Mid(V,H)	:= a[(l+r) div 2](V,H);Split	lda lptr	; get lptr	sta iptr	; store in iptr	lda rptr	; get rptr	sta jptr	; store in jptr	clc	; clear carry	adc iptr	; add both	ror A	; divide by 2 with carry from add	and #$FFFC	; put back onto a point boundary* A contains the y index into the point	buffer.  Load the actual key* values Point[y div 4].(V,H) into MidV	and MidH.	tay	; put index into y	lda [BufPtr],y	; get MidV	sta MidV	; save it	iny	; bump y	iny	; bump y	lda [BufPtr],y	; get MidH	sta MidH	; save it* ....repeat { scan	for keys out of order, then swap }* Scan the partition for points out of order with respect to a* screening point randomly selected in the middle.  First scan* upwards from iptr, then downwards from jptr, to set the limits* of a partition which is out of order.Scan	ldy iptr	; load iptr into y	lda MidV	; get screening value	bra ScanIEntry	; skip around increment* ......while a[iptr] < Mid do iptr := iptr+1NextIScan	IncYPtr	; bump y to next pointScanIEntry	cmp [BufPtr],y	; set flags on MidV-pts[iptr].v	bmi Scan2	; if we had to borrow, we've found	bne NextIScan	; if plus, look at the next one	lda MidH	; get screening value	IncYWd	; bump y to h value	cmp [BufPtr],y	; set flags on MidH-pts[iptr].h	bmi Scan2a	; if we had to borrow, we've found	beq Scan2a	; or if equal, we're still done	IncYWd	; point iptr at next entry	lda MidV	; reload A	bra ScanIEntry	; jump back and continue scanning* note that A still	contains MidVScan2a	DecYWd	; remove h value bump	lda MidV	; reload v valueScan2	sty iptr	; save iptr away	ldy jptr	; get jptr value into y	bra ScanJEntry	; skip around decrement* ......while a[jptr] > Mid do jptr := jptr-1NextJScan	DecYPtr	; dec y to next pointScanJEntry	cmp [BufPtr],y	; set flags on MidV-pts[jptr].v	bmi NextJScan	; if we borrowed, look at next* The Order and PreOrder entry points need to be checked	bne Order	; if Midv > pts.v, look again	lda MidH	; get screening value	IncYWd	; bump y to h value	cmp [BufPtr],y	; set flags on MidH-pts[jptr].h	bpl PreOrder	; if carry set we've found it	tya	; put jptr in A	sec	; set carry before subtract	sbc #6	; decrement by 6	tay	; put it back into y	lda MidV	; restore A	bra ScanJEntry	; loop again* If Iptr <= Jptr bump both pointers.  If Iptr < Jptr, swap	them (Quickdraw* always swapped them.  Let's save a few instructions).* ......if i < j then { swap a[jptr] and a[iptr] }PreOrder	DecYWd	; put counter back by 2Order	sty jptr	; save y in jptr	cpy iptr	; set flags on jptr-iptr	bcc DnScan	; Yes, all done	beq NextIJ	; if same point, bump but don't swap	lda [BufPtr],y	; get point V	sta Temp	; save it	IncYWd	; bump y by 2	lda [BufPtr],y	; get point H	sta Temp+2	; save it also	ldy iptr	; get other point	lda [BufPtr],y	; get point V	tax	; save it in x	IncYWd	; bump y by 2	lda [BufPtr],y	; get point H	ldy jptr	; get jptr back	IncYWd	; bump y to H part	sta [BufPtr],y	; save point H	txa	; get v back	DecYWd	; bump y down to V part	sta [BufPtr],y	; save point V	ldy iptr	; get iptr back	lda Temp	; get V point	sta [BufPtr],y	; store V part	IncYWd	; bump y to H part	lda Temp+2	; get H part	sta [BufPtr],y	; store V partNextIJ	ldy iptr	; get iptr	IncYPtr	; bump it	sty iptr	; save it	ldy jptr	; get jptr	DecYPtr	; decrement it	sty jptr	; save it	cpy iptr	; set flags on jptr-iptr	bcc DnScan	; if iptr > jptr, we're done	jmp Scan	; continue sorting* ......until iptr > jptrDnScan	sec	lda rptr	; compute rptr - iptr	sbc iptr	;	sta temp	; save it	sec	; set carry again	lda jptr	; compute jptr - lptr	sbc lptr	;	cmp temp	; set flags on (jptr-lptr)-(rptr-iptr)	bcs AddLeft	; if (jptr-lptr) >=	(rptr-iptr) do leftAddRight	lda iptr	; get iptr	cmp rptr	; set flags on iptr-rptr	bcs NoRAdd	; if rptr > iptr then add partition	inc SpCount	; bump our stack counter	pha	; push iptr	lda rptr	; get rptr	pha	; push that tooNoRAdd	lda jptr	; set rptr := jptr below	sta rptr	; do it	bra RJoin	; catch up belowAddLeft	lda lptr	; get lptr	cmp jptr	; set flags on lptr-jptr	bcs NoLAdd	; if jptr > lptr then add partition	inc SpCount	; bump our stack counter	pha	; push lptr	lda jptr	; get jptr	pha	; push that tooNoLAdd	lda iptr	; get iptr	sta lptr	; lptr := iptr* ....until lptr >=	rptrRJoin	lda lptr	; get lptr	cmp rptr	; set flags on lptr-rptr	bcs DnSplit	; done if rptr > lptr	jmp Split	; split again and continue sorting* ..until s=0DnSplit	lda SpCount	; get our stack counter	beq DnPop	; if 0, we're through	jmp PopNext	; if not, sort the next partitionDnPop	rtl	; let's go home!	ENDP;                copy rgndefs/packrgn****************************************************************** Procedure PackRgn;** Converts a sorted	array of inversion points into a region.* Calls storage allocator to make more room and trim result	to* minimum size.  Output is in the following form:**    Rgnsize	     (minimum 10 bytes)*    RgnBBox	     (bounding box,	top:left:bottom:right)*    V1 H1,...,Hn Maxint (scan line, inv.pts on that line)*    V2 H1,...,Hm Maxint (next scan line where inv.pts. change)*    ...*    Maxint	     (no more scan lines)** The array of inversion points is in BufHandle and BufPtr.* The number of points is in PtCount, and the destination region* handle is passed in RgnHandleA and RgnPtrA.*****************************************************************	EXPORT iPackRgniPackRgn	PROC	lda #10	; minimum length region	sta [RgnPtrA]	; zero the region	lda #0	; for clearing	ldy #2	; offset to top	sta [RgnPtrA],y	; top := 0	ldy #4	; offset to left	sta [RgnPtrA],y	; left := 0	ldy #6	; offset to bottom	sta [RgnPtrA],y	; bottom := 0	ldy #8	; offset to right	sta [RgnPtrA],y	; right := 0	lda #4	; examine point count	cmp PtCount	; set flags on 4-PtCount	bcc NotRect	; if PtCount > 4, we have more work	bne DnRect	; if PtCount <> 4, leave as null region* Move point at [BufPtr]+4 to BBox.TopLeft, [BufPtr]+12 to BBox.BotRight	tay	; y := 4, offset to	top	lda [BufPtr],y	; get top	ldy #2	; BBox.Top offset	sta [RgnPtrA],y	; set top	ldy #6	; offset to left	lda [BufPtr],y	; get it	ldy #4	; BBox.Left offset	sta [RgnPtrA],y	; set left	ldy #16	; offset to bottom	lda [BufPtr],y	; get it	ldy #6	; BBox.Bottom offset	sta [RgnPtrA],y	; set bottom	ldy #18	; offset to right	lda [BufPtr],y	; get it	ldy #8	; BBox.Right offset	sta [RgnPtrA],y	; set rightDnRect	ldy #10	; minimum region length	jmp TidyUp	; fix up size* BBox.Top := Point[1].VNotRect	ldy #4	; offset to first point v	lda [BufPtr],y	; get it	ldy #2	; offset to BBox.Top	sta [RgnPtrA],y	; save it	ldy #6	; offset to first point.h	lda [BufPtr],y	; get it	sta MinH	; MinH := Point[1].H	sta MaxH	; MaxH := Point[1].H* Y is still 6	ldx PtCount	; x will be our loop counterScan	Dex	; any points left?	Beq EndScan	; if not, quit scanning	IncYPtr	; bump y to next point	lda [BufPtr],y	; get next point	cmp MinH	; set flags on H-MinH	bpl TryMax	; if H >= MinH, check max	sta MinH	; MinH := H	bra Scan	; continueTryMax	cmp MaxH	; set flags on H-MaxH	bmi Scan	; if H < MaxH, we're cool	sta MaxH	; if H <= MaxH, MaxH := H	bra ScanEndScan	ldy #4	; BBox.Left offset	lda MinH	; get minimum H	sta [RgnPtrA],y	; set left	ldy #8	; BBox.Right offset	lda MaxH	; get maximum H	sta [RgnPtrA],y	; set right	lda PtCount	; get PtCount	asl A	; multiply by 2	asl A	; multiply by 4	tay	; put in y	lda [BufPtr],y	; get last point V (-4 offset built in)	ldy #6	; BBox.Bottom offset	sta [RgnPtrA],y	; save bottom* Get PtCount, multiply by 4 and add 12	to get the maximum number of* bytes we'll need to store the packed region.	lda PtCount	; get pointcount	ina	; by 1 to include stuff at beginning	asl A	; multiply by 2	asl A	; multiplied by 4	adc #12	; carry should be clear, add 12	ldx #RgnHandleA	; get offset to destination handle	jsr ResizeHandle	; resize A handle	bcs ErrorHandler	; if error set, quit	sta RgnPtrA	; save pointer	stx RgnPtrA+2	ldy #4	; offset to first inversion point	sty iptr	; save it	lda #10	; offset to first stored point	sta jptr	; save it	lda [BufPtr],y	; get top	ldx PtCount	; x is our loop counter again	bra Start	; do itErrorHandler	rtl	; leave with A and carry intactNextPt	ldy iptr	; set y to iptr	lda [BufPtr],y	; examine V point	cmp CurY	; set flags on V-CurrentY	beq VSame	; if same, add H point	sty iptr	; save iptr	ldy jptr	; switch to jptr	lda #MaxInt	; get end of row signal	sta [RgnPtrA],y	; put it	IncYWd	; bump jptr	sty jptr	; and save itStart	ldy iptr	; get iptr	lda [BufPtr],y	; get V point	sty iptr	; save iptr	ldy jptr	; get jptr	sta CurY	; keep track of it	sta [RgnPtrA],y	; put new V value	IncYWd	; bump it to H offset	sty jptr	; and save it* y should be pointing at a v offset when we get to VSame, either by falling* through from Start or branching here from NextPt	ldy iptr	; get iptrVSame	IncYWd	; bump y to h offset	lda [BufPtr],y	; get h value	IncYWd	; bump iptr to V offset	sty iptr	; save iptr	ldy jptr	; get jptr	sta [RgnPtrA],y	; put H value	IncYWd	; bump jptr	sty jptr	; save jptr	dex	; decrement our counter	bne NextPt	; if x <> 0, do another point* Put maxint twice as end of region marker.  Y register is still jptr	lda #MaxInt	; get Maxint signal	sta [RgnPtrA],y	; put signal end of	scan line	IncYWd	; bump it to end of	region	sta [RgnPtrA],y	; put signal end of	region	IncYWd	; y is now length of regionTidyUp	tya	; put y into A	ldx #RgnHandleA	; offset to RgnHandleA	jsr ResizeHandle	; resize it	sta RgnPtrA	; save pointer	stx RgnPtrA+2	rtl	; leave, and propogate any error	ENDP;                copy rgndefs/makergn****************************************************************** Procedure OpenRgn;** 3/29/89	mensch* Changed the error code reported for already open to $0430 like * the bopok says...*****************************************************************	EXPORT OpenRgnOpenRgn	PROC*              using RegionData*              using CoreDATAOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Next	equ RTL2+3* get address of GrafPort into y	jsr QDStart	jsr RgnSave	; are we already saving one?	bcs OpenError	; yes, give him an error	ldy #o_RgnSave+2	; offset to high word	lda [PortRef],y	; get next word	bne OpenError	; and complain again	ldx #BufHandle	; place to put new handle	lda #256	; initial size to allocate	jsr GetNewHandle	; get us a new buffer	bcs HandleError	; handle any error we find	sta BufPtr	; save pointer	stx BufPtr+2	lda BufHandle	; get low word of handle	ldy #o_RgnSave	; offset to store it in grafport	sta [PortRef],y	; store into RgnSave	lda BufHandle+2	; get high word	ldy #o_RgnSave+2	; offset to high word in grafport	sta [PortRef],y	; store into RgnSave+2	ldy #2	; index offset	lda #4	; initial length (0	points)	sta [BufPtr],y	; set first available offset	ldx #BufHandle	; get offset to BufHandle	jsr UnLockHandle	; unlock the handle	_HidePen	; hide the pen	jmp BusyEC0HandleError	tax	; propogate the error	jmp BusyErr0OpenError		ldx #RgnAlreadyOpen	; get error code;	ldx #$4031	; WHY IS THIS HERE?	jmp BusyErr0	; tell him about it	ENDP****************************************************************** Procedure CloseRgn(*   dstRgn : RgnHandle*   )*****************************************************************CloseRgn	PROC EXPORTOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3dstRgn	equ RTL2+3	jsr QDStart	jsr RgnSave	; are we saving one?	bcs @Continue	lda #rgnNotOpen	bra HandleError@Continue	lda #0	; prepare for clear	ldy #o_RgnSave	; offset to low word	sta [PortRef],y	; zero lo word of old handle	ldy #o_RgnSave+2	; offset to RgnSave+2 in PortRef	sta [PortRef],y	; zero hi word of old handle	_ShowPen	; undo the HidePen from OpenRgn	ldx #BufHandle	; get offset to BufHandle	jsr DerefHandle	; dereference and lock	sta BufPtr	; save pointer	stx BufPtr+2	ldy #2	; get index offset	lda [BufPtr],y	; get index	lsr A	; divided by 2	lsr A	; divided by 4	dea	; minus 1, now it's the # of points	sta PtCount	; keeps our current	point count	lda DstRgn,s	; get DstRgn handle	sta RgnHandleA	; save it	lda DstRgn+2,s	; get DstRgn handle	hi word	sta RgnHandleA+2	; save it too	ldx #RgnHandleA	; get offset to RgnHandleA	jsr DerefHandle	; dereference it	sta RgnPtrA	; save pointer	stx RgnPtrA+2	jsl SortPoints	; quicksort in VH order	jsl CullPoints	; cancel duplicate pairs	jsl PackRgn	; pack points into RgnHandleA (DstRgn)	stz PtCount	; clear PackRgn error flag	bcc PackOkay	inc PtCount	; save error condition	sta Op	; save error codePackOkay	ldx #BufHandle	; get offset	jsr UnLockHandle	; unlock the buffer	ldx #RgnHandleA	; get offset	jsr UnLockHandle	; unlock this too	PushLong BufHandle	; push buffer handle	_DisposeHandle	ldy PtCount	; see if we got a PackRgn error first	beq NoPackErr	; nope, look for a dispose error	ldx Op	jmp BusyErr4NoPackErr	bcs HandleError	; if carry set, it didn't workCloseDone	jmp BusyEC4HandleError	tax	jmp BusyErr4	ENDP;                copy rgndefs/rgnscan****************************************************************** Procedure ExpandA*****************************************************************	EXPORT ExpandAExpandA	PROC	lda #10	; size of rectangular region	cmp [RgnPtrA]	; set flags on 10-length	bne NotRect	; if not Rect, deal	with that	Movelong Scratch,PtrBaseA ; pointer to first fake region	ldy #2	lda [RgnPtrA],y	; BBox.Top	sta [PtrBaseA]	; V 1	ldy #4	lda [RgnPtrA],y	; BBox.Left	ldy #2	sta [PtrBaseA],y	; H 1.1	ldy #10	sta [PtrBaseA],y	; H 2.1	ldy #6	lda [RgnPtrA],y	; BBox.Bottom	ldy #8	sta [PtrBaseA],y	; V 2	lda [RgnPtrA],y	; BBox.RIght	ldy #4	sta [PtrBaseA],y	; H 1.2	ldy #12	sta [PtrBaseA],y	; H 2.2	lda #MaxInt	ldy #6	sta [PtrBaseA],y	; store MaxInt	ldy #14	sta [PtrBaseA],y	; store MaxInt	ldy #16	sta [PtrBaseA],y	; store MaxInt	stz PtrA	; zero PtrA	rts	; get outa hereNotRect	Movelong RgnPtrA,PtrBaseA ; use the actual pointer	lda #10	; get offset to data	sta PtrA	; save it	rts	; get outa here	ENDP****************************************************************** Procedure ExpandB*****************************************************************	EXPORT ExpandBExpandB	PROCFakeOff	equ 18	; offset in Scratch	to FakeB	lda #10	; size of rectangular region	cmp [RgnPtrB]	; set flags on 10-length	bne NotRect	; if not Rect, deal	with that	Movelong Scratch,PtrBaseB ; point us at	Scratch region	ldy #2	; offset to BBox	lda [RgnPtrB],y	; BBox.Top	ldy #FakeOff	sta [PtrBaseB],y	; V 1	ldy #4	lda [RgnPtrB],y	; BBox.Left	ldy #2+FakeOff	sta [PtrBaseB],y	; H 1.1	ldy #10+FakeOff	sta [PtrBaseB],y	; H 2.1	ldy #6	lda [RgnPtrB],y	; BBox.Bottom	ldy #8+FakeOff	sta [PtrBaseB],y	; V 2	ldy #8	lda [RgnPtrB],y	; BBox.RIght	ldy #4+FakeOff	sta [PtrBaseB],y	; H 1.2	ldy #12+FakeOff	sta [PtrBaseB],y	; H 2.2	lda #MaxInt	ldy #6+FakeOff	sta [PtrBaseB],y	; store MaxInt	ldy #14+FakeOff	sta [PtrBaseB],y	; store MaxInt	ldy #16+FakeOff	sta [PtrBaseB],y	; store MaxInt	lda #FakeOff	; get fake offset	sta PtrB	; offset to B	rts	; get outa hereNotRect	Movelong RgnPtrB,PtrBaseB ; use the real region	lda #10	; get offset to data	sta PtrB	; save it	rts	; get out here	ENDP****************************************************************** Procedure SectScan**   Accepts offsets	into Scratch buffer	in Src1, Src2, and*   Dst.  It then calculates the intersection, difference,*   or union of two	inversion scans.  Each input scan is a*   sorted array of	integers terminated	by MaxInt.  The output*   scan contains the inversion coordinates for the result.*****************************************************************	EXPORT SectScanSectScan	PROC	stz State1	; reset State1 off	stz State2	; reset State2 off	bra Share	; share code	EXPORT DiffScanDiffScan		;       	stz State1	; reset State1 off	lda #$FFFF	; get "on"	bra Union2	; share code	EXPORT UnionScanUnionScan		;       	lda #$FFFF	; get "on"	sta State1	; set State2 onUnion2	sta State2	; set State1 onShare	ldy Src1	; get Next1	lda [SrcBase1],y	sta Next1	; save it	IncYWd	; bump y	sty Src1	ldy Src2	; get Next2	lda [Scratch],y	sta Next2	IncYWd	sty Src2Next	lda Next2	; get Next2	cmp Next1	; set flags on Next2-Next1	bmi Less2	; if Next2 < Next1,	process 2nd	bne Less1	; if Next1 < Next2,	process 1stEqual	cmp #MaxInt	; is it MaxInt	beq Done	; if so, we're done	lda State1	; get State1	cmp State2	; are states the same?	bne Skip0	; no, skip	lda Next1	; get it back	ldy Dst	; get destination	sta [Scratch],y	; put it	IncYWd	; bump y	sty Dst	; save Dst counterSkip0	ldy Src1	; get A ptr	lda [SrcBase1],y	; get Next1	sta Next1	; save it	IncYWd	; bump y	sty Src1	; save y	lda State1	; get State1	eor #$FFFF	; not #1	sta State1	; save it	ldy Src2	; get index	lda [Scratch],y	; get Next2	sta Next2	; save it	IncYWd	; bump y	sty Src2	; save y	lda State2	; get State2	eor #$FFFF	; not #2	sta State2	; save it	bra Next	; loop for moreLess1	lda State2	; test State2	beq Skip1	; skip if not true	lda Next1	; get A	ldy Dst	; get destination	sta [Scratch],y	; save it	IncYWd	; bump y	sty Dst	; save DstSkip1	ldy Src1	lda [SrcBase1],y	; get next value	sta Next1	; save it	IncYWd	; bump y	sty Src1	; save it	lda State1	; get state	eor #$FFFF	; not State1	sta State1	; save it	bra Next	; loop for moreLess2	lda State1	; test State1	beq Skip2	; skip if not true	lda Next2	; get B	ldy Dst	; get destination	sta [Scratch],y	; save it	IncYWd	; bump y	sty Dst	; save DstSkip2	ldy Src2	; get Next2	lda [Scratch],y	; get next value	sta Next2	; save it	IncYWd	; bump y	sty Src2	; save it	lda State2	; get state	eor #$FFFF	; not State2	sta State2	; save it	jmp Next	; loop for moreDone	lda #MaxInt	; get maxint	ldy Dst	; get pointer	sta [Scratch],y	; store end of scan	IncYPtr	; bump y	sty Dst	; make count valid	rts	; we're out of here	ENDP****************************************************************** Procedure InsetScan**   Accepts offsets	into Scratch buffer	in Src1 and*   Dst.  It then horizontally insets an inversion scan by DH.*   The input scan is a sorted array of	integers terminated	by*   MaxInt.  The output scan contains the inversion coordinates*   for the inset.**   1/20/88 GCP Added test to outsetscan to check for equal	points.****************************************************************	EXPORT InsetScanInsetScan	PROC	lda DH	; is dh negative?	bmi Outset	; yes, outsetInset	ldy Src1	; get first offset	lda [SrcBase1],y	; get first value	sta Temp	; save it	cmp #MaxInt	; check for terminator	beq DoneOutSet	; quit when found	IncYWd	; bump y	lda [SrcBase1],y	; get second value	IncYWd	; bump y again	sty Src1	; save it	sec	; prepare for subtract	sbc DH	; subtract from right	sta Temp+2	; save it also	lda Temp	; get first back	clc	; prepare for add	adc DH	; add to left	sta Temp	; save it	cmp Temp+2	; set flags on left-right	bpl Inset	; if left >= right,	skip both	ldy Dst	; get destination offset	sta [Scratch],y	; save first	IncYWd	; bump y	lda Temp+2	; get first back	sta [Scratch],y	; save second	IncYWd	; bump y	sty Dst	; save pointer	bra Inset	; loop entire scanDoneOut	sty Src1	; update itDoneOutSet	ldy Dst	; get destination pointer	lda #MaxInt	; get end of scan	sta [Scratch],y	; mark it	IncYWd	; bump y	sty Dst	; there!	rts	; All done!* each pair of coords, outset them and cancel if they crossOutset	lda #-MaxInt	; set oldrightOutsetLoop	sta OldRight	; to -Maxint	ldy Src1	; get next offset	lda [SrcBase1],y	; load next left value	IncYWd	; bump it	sta Temp	; save it	cmp #MaxInt	; check for terminator	beq DoneOut	; if it is, we're done	lda [SrcBase1],y	; get right value	IncYWd	; bump y	sty Src1	; save it	ldy Dst	; get ready for store	sec	; prepare for subtract	sbc DH	; right-DH	sta Temp+2	; save it	lda Temp	; get left back	clc	; prepare for add	adc DH	; add to left	cmp OldRight	; is left <= OldRight	beq Around	bpl OutOk	; no, continueAround	DecYWd	; decrement Dst by 2	bra OutOk2	; and continueOutOk	sta [Scratch],y	; save left point	IncYWd	; bump yOutOk2	lda Temp+2	; get right back	sta [Scratch],y	; save right point	IncYWd	; bump y	sty Dst	; save it	bra OutsetLoop	; loop for entire scan	ENDP****************************************************************** Procedure XorScan**   Accepts offsets	into Scratch buffer	in Src1, Src2, and*   Dst.  It then forms the exclusive or of two inversion scans.*   Each input scan	is a sorted array of integers terminated by*   MaxInt.  The output scan contains all input coordinates	from*   each, but with duplicate pairs cancelled.  It also is*   terminated by MaxInt.** 3/7/89	Konstantin** 	Removed variables Next1 and Next2, and made loops*	tighter and faster.*  ****************************************************************	EXPORT XorScanXorScan	PROC	ldx Dst	ldy Src2	; get offset to ADoNext	lda [Scratch],y	; get Next 	ldy Src1	; get next B offset	cmp [SrcBase1],y	; compare with next1		bmi Less2	bne Less1	; if Next1 < Next2,	take from 1Equal	ldy Src1	;Worst case: 5 cycles	IncYWd	;4 cycles	sty Src1	;Worst case: 5 cycles		ldy Src2		IncYWd		sty Src2			cmp #MaxInt	; all done?	bne DoNext	;y-reg  contains Src2	XorScanDone	txy	sta [Scratch],y	; save terminator, y already = Dst	rts	; go homeLess2		;a contains value pointed to by src2	txy	sta [Scratch],y	; save the second value	inx	; bump Dst	inx	; and save it	ldy Src2	; get offset to A	IncYWd	sty Src2	lda [Scratch],y	; get Next A	ldy Src1	; get next B offset	cmp [SrcBase1],y	; compare with next1		bmi Less2	bne Less1	; if Next1 < Next2,	take from 1	bra EqualLess1		;y contains Src1	lda [SrcBase1],y	IncYWd	sty Src1		txy	sta [Scratch],y	; put it	inx	; bump Dst	inx	; and save it	ldy Src2	; get offset to A	lda [Scratch],y	; get Next A	ldy Src1	cmp [SrcBase1],y	; compare with next1		bmi Less2	bne Less1	; if Next1 < Next2,	take from 1	bra Equal	ENDP;                copy rgndefs/rgnop****************************************************************** Procedure RgnOp;**   Accepts two source regions in RgnHandleA and RgnHandleB	and*   assumes they have been dereferenced	and locked down.  It*   creates a buffer based on PtCount.	The horizontal offset*   used in the event of and InsetRgn call is passed in register*   X.  The operation to perform is passed in Op.**   Computes the intersection, difference, union, or xor of*   two regions or the horizontal inset	of one region, and stores*   the result as an unpacked array of sorted inversion points*   in bufHandle.  Returns the number of points in PtCount.*   BufHandle will be grown only if more space is needed.  RgnOp*   returns an error if one is returned	from the memory manager.**    Sect = 0   A-B	Diff = 2   Union = 4   Xor = 6   HInset	= 8*****************************************************************	EXPORT iRgnOpiRgnOp	PROC* We generate some scratch space - an awful process but we have to get* the memory we need from somewhere - might as well grab it	all at once.* Here follows the usage of that memory.FakeA	equ 0	; offset to FakeA regionFakeB	equ FakeA+18	; offset to FakeB regionScan	equ FakeB+18	; offset to start of scan buffersScratchSize	equ 10280	; 10 K of space, maximumPartition	equ 2048	; size of one partition	stx DH	; save horizontal offset	stz BufHandle	; zero handle to nil	stz BufHandle+2** NEW CODE* 1/6/88* This is the new region cache code.* On the third zero	page (only place left) at "RgnCache" there* is a handle to 10Kbytes of memory for	use as a temporary working area for* rgnops. This cache is purgable so each time we call region op we check to see* if the handle is empty. If the handle	has been purged then we restore the* handle, if is has	not been purged then we reuse it.* The initial call to allocate the cache memory is made in QDStartUp.* The handle is locked while we are in this routine and unlocked on exit.*DerefAgain	ldx #RgnCache	;deref and lock the handle	jsr DeRefHandle	cmp #0	;both will be zero if cache has been	bne CacheEst	;purged	cpx #0	bne CacheEst	;branch if cache is	still allocated	ldx #RgnCache	lda 2,x	;put cache handle on stack	pha	lda 0,x	pha	_RestoreHandle	;reallocates space for cache		;The handle must already be the right size	bcc DerefAgain	sec	;indicate error	rtlCacheEst		; T1	sta Scratch	; save pointer	stx Scratch+2	lda PtCount	; get size of BufHandle	ldx #BufHandle	; get offset	jsr GetNewHandle	bcc T2	; if an error, return it	brl MemErrorT2	sta BufPtr	stx BufPtr+2	ldy #2	lda #4	sta [BufPtr],y	; initialize buffer	index* Move RgnPtrA to FakeA and expand it to a 4 point packed region if rectangular	jsr ExpandA	; expand FakeA	jsr ExpandB	; expand FakeB* Initialize assorted pointers	sec	; prepare for subtract	lda PtCount	; get size of BufHandle	sbc #4	; remove length and	index bytes	and #$FFF8	; truncate to an integral # of points	clc	; prepare for add	adc #4	; put length and index bytes back in	sta ListMax	; biggest we can handle	ldy #4	; offset to first buffer dest	sty ListPtr	; save it	ldy #Scan	; offset to first scan buffer	lda #MaxInt	; get MaxInt	sta [Scratch],y	; initialize ScanA to empty	sty ScanA	; save it in ScanA	ldy #(Scan+Partition) ; offset to second scan buffer	sta [Scratch],y	; initialize ScanB to empty	sty ScanB	; save it in ScanB	ldy #(Scan+Partition*2) ; offset to third scan buffer	sta [Scratch],y	; initialize ScanC to empty	sty ScanC	; save it in ScanC	ldy #(Scan+Partition*3) ; offset to fourth scan buffer	sty TempScan	; save it in TempScan	ldy #(Scan+Partition*4) ; offset to fifth scan buffer	sty OutScan	; save it in OutScan	Movelong Scratch,SrcBase1 ; initialize SrcBase1	ldy PtrA	; get PtrA	lda [PtrBaseA],y	; NextA := first vert in A	sta NextA	; save it	IncYWd	; bump y to next word	sty PtrA	; save it	ldy PtrB	; get PtrB	lda [PtrBaseB],y	; NextB := first vert in B	sta NextB	; save it	IncYWd	; bump y to next word	sty PtrB	; save it	lda Op	; get Op	cmp #8	; is it Inset	bne NxtVert	; no, continue	lda #MaxInt	; get maxint	sta NextB	; save it in NextBNxtVert	lda NextA	; get NextA	cmp NextB	; set flags on NextA - NextB	beq Both	; they're equal, bump both	bpl UpdateB	; B, update RgnB only	jsr UpdateA	; A, update RgnA only	bra CalcUpdateA	lda NextA	; get NextA	sta Vert	; Vert := NextA	Movelong PtrBaseA,SrcBase1 ; establish the source base pointer	ldy PtrA	; get PtrA	sty Src1	; Src1 := PtrA	ldy ScanA	; get ScanA	sty Src2	; Src2 := ScanA	ldy TempScan	; get TempScan	sty Dst	; Dst := TempScan	jsr XorScan	; XorScan(PtrA,ScanA,TempScan)	Movelong Scratch,SrcBase1 ; put it back	where it belongs	ldy Src1	; get Src1; y is PtrA, bu	lda [PtrBaseA],y	; get next vert	sta NextA	; NextA := next Vert	IncYWd	; bump y	sty PtrA	; save it	ldx TempScan	; get TempScan	lda ScanA	; get ScanA	stx ScanA	; swap them	sta TempScan	; like so	rts	; return to local caller* When we get to Both, the A register contains the next vertical.  If it* is Maxint, we're done.XDone	jmp Done	; relay branchBoth	cmp #MaxInt	; is it Maxint?	beq XDone	; if so, all done	jsr UpdateA	; update RgnAUpdateB	lda NextB	; vert := NextB	sta Vert	; do it	Movelong PtrBaseB,SrcBase1 ; establish the source base pointer	lda PtrB	; get PtrB	sta Src1	; Src1 := PtrB	lda ScanB	; get ScanB	sta Src2	; Src2 := ScanB	lda TempScan	; get TempScan	sta Dst	; Dst := TempScan	jsr XorScan	; XorScan(PtrB,ScanB,TempScan)	Movelong Scratch,SrcBase1 ; put it back	where it belongs	ldy Src1	; get Src1	lda [PtrBaseB],y	; get next vert	sta NextB	; NextB := next vert	IncYWd	; bump y	sty PtrB	; PtrB := end of scan + 2	ldx TempScan	; get temp scan	lda ScanB	; get ScanB	stx ScanB	; swap them	sta TempScan	; like so* Calculate sect, diff, union, xor, or inset into ScanCCalc	lda ScanA	; get ScanA	sta Src1	; Src1 := ScanA	lda ScanB	; get ScanB	sta Src2	; Src2 := ScanB	lda TempScan	; get TempScan	sta Dst	; Dst := TempScan	ldx Op	; fetch Op (0,2,4,6,8)	jsr (CaseTab,x)	; execute OpScan	bra Changes	; jump around casetabCaseTab	DC.W SectScan	; address of SectScan	DC.W DiffScan	; address of DiffScan	DC.W UnionScan	; address of UnionScan	DC.W XorScan	; address of XorScan	DC.W InsetScan	; address of InsetScanChanges	lda TempScan	; get TempScan	sta Src1	; Src1 := TempScan	lda ScanC	; get ScanC	sta Src2	; Src2 := ScanC	ldy OutScan	; get offset to OutScan	sty Dst	; Dst := OutScan	jsr XorScan	; XorScan(TempScan,ScanC,OutScan)	ldx TempScan	; get TempScan	lda ScanC	; get ScanC	stx ScanC	; swap them	sta TempScan	; like so	ldy OutScan	; where the data was placed	sty Src1	; index we'll use to fetch it	ldy ListPtr	; so the comparison	will work	bra OutTest	; go to loop startOutLoop	lda [Scratch],y	; get H coord from OutScan	sta Temp	; save it	IncYWd	; bump y to next H offset	lda [Scratch],y	; get next H coord from OutScan	sta Temp+2	; save it too	IncYWd	; bump y again	sty Src1	; tuck it away	ldy ListPtr	; get output destination offset	lda Vert	; get V back	sta [BufPtr],y	; save it	IncYWd	; bump y	lda Temp	; get H	sta [BufPtr],y	; save it	IncYWd	; bump y	lda Vert	; get V value	sta [BufPtr],y	; save it	IncYWd	; bump y	lda Temp+2	; get H	sta [BufPtr],y	; save it	IncYWd	; bump y	sty ListPtr	; save itOutTest	cpy ListMax	; set flags on ListPtr-ListMax	bcc SizeOk	; if ListMax > ListPtr, continue* The point buffer is full.  Grow it if	Flags <> 0.	lda ListMax	; get current useful size	clc	; clear carry	adc #256	; bump by 256 bytes	sta ListMax	; the new value, already trimmed	ldx #BufHandle	; get offset	jsr ResizeHandle	; resize it, relock	it	bcs MemError	sta BufPtr	; save new pointer	stx BufPtr+2SizeOk	ldy Src1	; get offset to next value from OutScan	lda [Scratch],y	; get the next H coord	cmp #MaxInt	; is it MaxInt?	bne OutLoop	; no, go for more	jmp NxtVert	; loop for next vertMemError	pha	; save error	ldx #RgnCache	jsr UnlockHandle	pla	; get error back	sec	; ensure error flag	is set	rtlDone	ldy #2	; offset to ListPtr	index	lda ListPtr	; get size	sta [BufPtr],y	; save size	lsr A	; divide by 2	lsr A	; divided by 4	dea	; minus 1 to generate # of points	sta PtCount	; update itGetRidOfS	ldx #RgnCache	jsr UnlockHandle	clc	rtl	; get out of here	ENDP;                copy rgndefs/sectrgn****************************************************************** Procedure RgnAEmpty**   Local procedure	which checks RgnA (assumed dereferenced	in*   RgnPtrA) to see	if it is empty.  It	checks both the vertical*   and the horizontal for emptiness, and leaves the carry set*   if they are, and clear if it's not empty.*****************************************************************	EXPORT RgnAEmptyRgnAEmpty	PROC	ldy #BBoxLeft	; offset to left	lda [RgnPtrA],y	; get left	ldy #BBoxRight	; offset to right	cmp [RgnPtrA],y	; set flags on left-right	bpl Done	; if left >= right,	copy	ldy #BBoxTop	; offset to top	lda [RgnPtrA],y	; get top	ldy #BBoxBottom	; offset to bottom	cmp [RgnPtrA],y	; set flags on top-bottomDone	rts	; carry is set correctly, leave	ENDP****************************************************************** Procedure RgnBEmpty**   Local procedure	which checks RgnB (assumed dereferenced	in*   RgnPtrB) to see	if it is empty.  It	checks both the vertical*   and the horizontal for emptiness, and leaves the carry set*   if they are, and clear if it's not empty.*****************************************************************	EXPORT RgnBEmptyRgnBEmpty	PROC	ldy #BBoxLeft	; offset to left	lda [RgnPtrB],y	; get left	ldy #BBoxRight	; offset to right	cmp [RgnPtrB],y	; set flags on left-right	bpl Done	; if left >= right,	copy	ldy #BBoxTop	; offset to top	lda [RgnPtrB],y	; get top	ldy #BBoxBottom	; offset to bottom	cmp [RgnPtrB],y	; set flags on top-bottomDone	rts	; carry is set correctly, leave	ENDP****************************************************************** Procedure RgnSector**   Takes the regions in RgnPtrA and RgnPtrB and intersects*   their bounding boxes, leaving the resulting rectangle in*   RgnY1, RgnX1, RgnY2, and RgnX2 on zero page.  Called below*   and by RectInRgn.*****************************************************************	EXPORT RgnSectorRgnSector	PROC	ldy #BBoxTop	; offset to top	lda [RgnPtrA],y	; get first top	cmp [RgnPtrB],y	; compare to second	bpl STop	; if A > B, use A	lda [RgnPtrB],y	; get the other oneSTop	sta RgnY1	; save Top	ldy #BBoxBottom	; offset to bottom	lda [RgnPtrB],y	; get second bottom	cmp [RgnPtrA],y	; compare to first	bmi SBottom	; if B < A, use B	lda [RgnPtrA],y	; get other oneSBottom	sta RgnY2	; save bottom	ldy #BBoxRight	; offset to right	lda [RgnPtrB],y	; get second right	cmp [RgnPtrA],y	; compare to first	bmi SRight	; if B < A, use B	lda [RgnPtrA],y	; get the other oneSRight	sta RgnX2	; save right	ldy #BBoxLeft	; offset to left	lda [RgnPtrA],y	; get first left	cmp [RgnPtrB],y	; compare to second	bpl SLeft	; if A > B, use A	lda [RgnPtrB],y	; get the other oneSLeft	sta RgnX1	; save left	rts	ENDP****************************************************************** Procedure SectRgn(*   srcRgnA,srcRgnB,dstRgn:RgnHandle*   )**   Calculate the intersection of two regions.*****************************************************************	EXPORT SectRgnSectRgn	PROC	jsr QDStart	lda #0	; op := Sect	jmp DoRgnOp	; it does all the work	ENDP****************************************************************** Procedure UnionRgn(*   srcRgnA,srcRgnB,dstRgn:RgnHandle*   )**   Calculate the union of two regions.*****************************************************************	EXPORT UnionRgnUnionRgn	PROC	jsr QDStart	lda #4	; op := Union	jmp DoRgnOp	; it does all the work	ENDP****************************************************************** Procedure DiffRgn(*   srcRgnA,srcRgnB,dstRgn:RgnHandle*   )**   Calculate the difference A-B of two	regions.*****************************************************************	EXPORT DiffRgnDiffRgn	PROC	jsr QDStart	lda #2	; op := Diff	jmp DoRgnOp	; it does all the work	ENDP****************************************************************** Procedure XorRgn(*   srcRgnA,srcRgnB,dstRgn:RgnHandle*   )**   Calculate the exclusive or of two regions.*****************************************************************	EXPORT XorRgnXorRgn	PROC	jsr QDStart	lda #6	; op := Xor	jmp DoRgnOp	; it does all the work	ENDP****************************************************************** Procedure DoRgnOp;**   Computes the Intersection, Difference, Union, or Xor*   of two regions.	 Enter with Op in A.**    Sect = 0	A-B Diff = 2      Union = 4      Xor = 6*****************************************************************	EXPORT DoRgnOpDoRgnOp	PROC*              using E0VectorsOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3DstRgn	equ RTL2+3SrcRgnB	equ DstRgn+4SrcRgnA	equ SrcRgnB+4	sta Op	; save the operation	pha	; room for result	lda SrcRgnA+4,s	; get high word	pha	; push it	lda SrcRgnA+4,s	; get low word	pha	; push it	lda SrcRgnA+4,s	; get high word	pha	; push it	lda SrcRgnA+4,s	; get low word	pha	; push it	_EqualRgn	; are they equal?	pla	; get boolean result	beq NotSame	; if 0 (false), we have more work	lda Op	; get op	and #2	; and it with 2 (Diff and Xor bit)	bne Zero	; zero it if Sect or UnionCopy	lda SrcRgnA+2,s	; get high word	pha	; push it	lda SrcRgnA+2,s	; get low word	pha	; push it	lda DstRgn+6,s	; get high word	pha	; push it	lda DstRgn+6,s	; get low word	pha	; push it	_CopyRgn	; copy it	bcs T1	jsr UnlockAB	jmp BusyEC12	; we can leave nowZero	lda DstRgn+2,s	; get high word	pha	; push it	lda DstRgn+2,s	; get low word	pha	; push it	_SetEmptyRgn	; zero the destination	bcs T1	jsr UnlockAB	jmp BusyEC12T1	pha	; save error code	jsr UnlockAB	plx	; restore error code	jmp BusyErr12* load the handles from the stack onto zero page and dereference themNotSame	lda SrcRgnA,s	; get low word of SrcRgnA	sta RgnHandleA	; save it	lda SrcRgnA+2,s	; get high word of SrcRgnA	sta RgnHandleA+2	; save it	jsr DerefA	lda SrcRgnB,s	; get low word of SrcRgnB	sta RgnHandleB	; save it	lda SrcRgnB+2,s	; get high word of SrcRgnB	sta RgnHandleB+2	; save it	jsr DerefB* If Op = Diff and RgnB is empty, copy RgnA into DstRgn	lda #2	; get Diff opcode	cmp Op	; is it Diff?	bcc UniXor	; if Op > Diff then	Union or Xor	bne BBoxes	; if Op <> Diff, it's Sect* Op = Diff, so check RgnB for empty	jsr RgnBEmpty	; is RgnB empty	bpl Copy	; if it's empty, CopyRgnA* If Op = Sect or Diff, then intersect the bounding boxes.BBoxes	jsr RgnSector	; RgnY1..RgnX2 := RgnA * RgnB	lda RgnX1	cmp RgnX2	; compare to X2	bpl Empty	; if X1=X2, it's empty	lda RgnY1	; get top	cmp RgnY2	; if Y1 >= Y2, it's empty	bmi NotEmpty	; so do it* The bounding boxes don't intersect.  If Op = Sect, then return empty.* If Op = Diff, then copy RgnA into DstRgnEmpty	lda Op	; get op	beq Zero	; if Sect, return empty	jmp Copy	; no, copy SrcA into DstRgn* If Op = Sect, then check for both inputs rectangularNotEmpty	lda Op	; is op = Sect	bne NotEasy	; no, continue	lda #10	; get rectangular region size	cmp [RgnPtrA]	; compare with RgnA	length	bne NotEasy	; no, continue	cmp [RgnPtrB]	; compare with RgnB	length	bne NotEasy	; no, continue* push dstrgn and address of temprect.	Could be bad news.	lda DstRgn+2,s	; get high word	pha	; push it	lda DstRgn+2,s	; get low word	pha	; push it	clc	lda #0	; it's in bank 0	pha	; push high word	tdc	; get direct register	adc #RgnY1	; add in offset	pha	; push low word	_RectRgn	; RectRgn(dstRgn,tempRect)	bcs T2	jsr UnlockAB	jmp BusyEC12T2	pha	; save error	jsr UnlockAB	plx	; restore error	jmp BusyErr12UniXor	jsr RgnBEmpty	; is RgnB empty?	bmi T3	; yes, copy RgnA	brl CopyT3	jsr RgnAEmpty	; is RgnA empty?	bmi NotEasy	; yes, copy RgnB	lda SrcRgnB+2,s	; get high word	pha	; push it	lda SrcRgnB+2,s	; get low word	pha	; push it	lda DstRgn+6,s	; get high word	pha	; push it	lda DstRgn+6,s	; get low word	pha	; push it	_CopyRgn	; copy it	bcs T4	jsr UnlockAB	jmp BusyEC12T4	pha	jsr UnlockAB	plx	jmp BusyErr12NotEasy	clc	; clear carry for addition	lda [RgnPtrA]	; get RgnA length	adc [RgnPtrB]	; add RgnB length	asl A	; double (Quickdraw	did ADD D4,D4)	sta PtCount	; save it* We've taken all the shortcuts we can.  Now we pass the buck to RgnOp to do* the real work.  The source regions are still in RgnHandleA and RgnHandleB.* PtCount contains the maximum size we should need.  Load X	with 0 since we* have no horizontal offset to worry about (just for cleanliness).	ldx #0	; unnecessary unless code changes	jsl RgnOp	; do it	bcs RgnOpError	; RgnOp propogates errors	lda DstRgn,s	sta RgnHandleA	lda DstRgn+2,s	sta RgnHandleA+2	jsr DerefA	jsl PackRgn	; call it	PushLong BufHandle	; push handle	_DisposeHandle	; dispose of point buffer handle	bcs T5	jsr UnlockAB	jmp BusyEC12T5	pha	; save error code	jsr UnlockAB	plx	; get error code back	jmp BusyErr12RgnOpError	pha	; save error code	_SysBeep	_SysBeep	lda BufHandle	ora BufHandle+2	beq DontDispose	ldx #BufHandle	jsr UnlockHandle	PushLong BufHandle	_DisposeHandleDontDispose	jsr UnlockAB	plx	; get error code back	jmp BusyErr12UnlockAB	ldx #RgnHandleA	jsr UnlockHandle	ldx #RgnHandleB	jsr UnlockHandle	rts	ENDP;                copy rgndefs/insetrgn****************************************************************** Procedure InsetRgn** Inputs: rgnHandle:RgnHandle*         dH:Integer*         dV:Integer* Description:*        Shrinks or	expands a specified	region. All points on the region*        boundary are moved inward a distance of dH horizontally and*        dV verticaly. If dh or dv are negative, the points	are moved*        outward in	that direction. Inset Rgn leaves the region centered on*        the same position but moves the outline. InsetRgn of a rect rgn works*        the same as insetRect.****************************************************************	EXPORT InsetRgnInsetRgn	PROC*              using E0VectorsOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Dvs	equ RTL2+3Dhs	equ Dvs+2Rgn	equ Dhs+2	jsr QDStart* Setup direct page	references to the region handle and pointer.	lda Rgn,s	sta RgnHandleA	lda Rgn+2,s	sta RgnHandleA+2	ldx #RgnHandleA	; offset	jsr DerefHandle	sta RgnPtrA	; save pointer	stx RgnPtrA+2* Is this region rectangular?	lda [RgnPtrA]	cmp #10	bne NotRect* This region is rectangular so we add the offset to the right and bottom* and subtract the offsets from the top	and left.	lda Dhs,s	sta Dh	; copy the parameters	lda Dvs,s	sta Dv	ldy #2	; I could call _InsetRect, but	lda [RgnPtrA],y	; that takes almost	as much code	clc	; to set up as just	doing it, and	adc Dv	; it will certainly	be slower.	sta [RgnPtrA],y	ldy #4	lda [RgnPtrA],y	clc	adc Dh	sta [RgnPtrA],y	ldy #6	lda [RgnPtrA],y	sec	sbc Dv	sta [RgnPtrA],y	ldy #8	lda [RgnPtrA],y	sec	sbc Dh	sta [RgnPtrA],yDone	ldx #RgnHandleA	jsr UnlockHandle	jmp BusyEC8ErrorReturn	pha	; save error	ldx #RgnHandleA	jsr UnlockHandle	plx	; restore error	jmp BusyErr8* RgnOp will do most of the work for us.  To call it, put the source in both* RgnHandleA and RgnHandleB.  It allocates BufHandle.  Pass	the horizontal* offset in register X, and pass the operation (HInset=8) in Op.  Pass the* expected size of BufHandle in PtCount.NotRect	lda Dhs,s	tax	jsr HInset	lda Dvs,s	tax	jsr HInset	bra Done	; above* End of the core of InsetHInset	MoveLong RgnHandleA,RgnHandleB ; in case PackRgn moved RgnA	MoveLong RgnPtrA,RgnPtrB	lda [RgnPtrA]	; get current size	asl A	; double it	sta PtCount	; save suggested length	lda #8	sta Op	jsl RgnOp	; creates BufHandle/BufPtr	bcs RgnOpError* *BufPtr struct is*         length: word*         Index: word*         pointlist: sorted array of inversion points.*	ldy #2	lda [BufPtr],y	; get index	sta PtCount	; temp variable	cmp #5	; did it drop to zero points?	bpl GotPoints	; no, so continue processing it* We don't have any points left so* Dispose of the buffer and set the region to empty* !!!!!!! Shouldn't this leave a minimum size rectangle !!!!!!!!!	ldx #BufHandle	jsr UnlockHandle	PushLong BufHandle	_DisposeHandle	; yes, so clean up	bcs ZeroError	; handle error	PushLong RgnHandleA	; zero out the region	_SetEmptyRgn	bcs ZeroError	plx	; pull Hinset return	brl DoneZeroError	tax	ply	; discard local return	jmp BusyErr8* We still have a region larger than empty* Swap the h and v positions in the buffer.* "I don't know why!"* Keep going until y = PtCount. Remember PtCount really contains [BufPtr],2*  the "index".GotPoints	ldy #4	; initialize our indexSwapLp	lda [BufPtr],y	; get V	pha	; save the v	IncYWd	; index to H	lda [BufPtr],y	; get H	tax	; put H into x	pla	; put V into a	sta [BufPtr],y	; save V where H used to be	txa	; get H back into a	DecYWd	; point back to where V used to be	sta [BufPtr],y	; save H	IncYPtr	cpy PtCount	; are we done yet?	bne SwapLp* y = PtCount. What	we want to do here is PtCount = (PtCount/4) - 1* remember that PtCount = index.ReSort	tya	; get index	lsr A	; divide by 4	lsr A	dea	; decrement it	sta PtCount	; save it* SortPoints takes the sorted array of points and does a quick sort on them* ??????????	jsl SortPoints	jsl PackRgn	; result is in RgnHandleA	bcs PackError	PushLong BufHandle	_DisposeHandle	; get rid of it	bcs DisposError	rts	; return to local caller* All done* Handle ErrorsRgnOpError	pha	; save error code	ldx #RgnHandleA	; unlock handle	jsr UnlockHandle	lda BufHandle	; was it ever allocated?	ora BufHandle+2	beq DontDispose	PushLong BufHandle	; deallocate bufhandle	_DisposeHandleDontDispose	plx	; retreive error code	ply	; pull local return	jmp BusyErr8PackError	pha	; save error code	ldx #RgnHandleA	; unlock handle	jsr UnlockHandle	PushLong BufHandle	_DisposeHandle	plx	; retrieve error code	ply	; discard local return	jmp BusyErr8DisposError	tax	ply	; discard local return	jmp BusyErr8	ENDP****************************************************************** Procedure OffsetRgn*****************************************************************	EXPORT OffsetRgnOffsetRgn	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Dvs	equ RTL2+3Dhs	equ Dvs+2Rgn	equ Dhs+2	jsr QDStart	lda Rgn,s	sta RgnHandleA	lda Rgn+2,s	sta RgnHandleA+2	lda Dhs,s	sta Dh	lda Dvs,s	sta Dv	ldx #RgnHandleA	; offset	jsr DerefHandle	sta RgnPtrA	; save pointer	stx RgnPtrA+2* Offset the bounding box	ldy #2	; offset the top	lda [RgnPtrA],y	clc	adc Dv	sta [RgnPtrA],y	ldy #4	; offset the left	lda [RgnPtrA],y	clc	adc Dh	sta [RgnPtrA],y	ldy #6	; offset the bottom	lda [RgnPtrA],y	clc	adc Dv	sta [RgnPtrA],y	ldy #8	; offset the right	lda [RgnPtrA],y	clc	adc Dh	sta [RgnPtrA],y	lda #10	; if rectangular, we're done	cmp [RgnPtrA]	beq Done	tay	lda [RgnPtrA],yNxtVert	clc	; offset the vertical	adc Dv	sta [RgnPtrA],y	IncYWd	lda [RgnPtrA],yNxtHor	clc	; offset 1st of horizontal pair	adc Dh	sta [RgnPtrA],y	IncYWd	lda [RgnPtrA],y	; offset 2nd of horizontal pair	clc	adc Dh	sta [RgnPtrA],y	IncYWd	lda [RgnPtrA],y	; check for end of scan line	cmp #MaxInt	bne NxtHor	IncYWd	lda [RgnPtrA],y	cmp #MaxInt	; check for end of region	bne NxtVertDone	ldx #RgnHandleA	jsr UnlockHandle	jmp BusyEC8	ENDP;                copy rgndefs/maprgn****************************************************************** MapRgn** Change History* 7/23/87      GCP	   MapRgn and PutRgn don't agree where the*	   the input to putrgn should be so it is*	   put in both locations.*****************************************************************	EXPORT MapRgnMapRgn	PROC*              using E0VectorsOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3ToRectPtr	equ RTL2+3FromRectPtr	equ ToRectPtr+4Rgn	equ FromRectPtr+4	jsr QDStart	jsr RetrieveRects;----------------------------------------------------------;; Are the rects different?  If not, we done.;	ldx #6	; 3RectLoop	lda FRect,x	; 2	cmp TRect,x	; 2	bne NotSame	; 2	dex	; 1	dex	; 1	bpl RectLoop	; 2	bra JDone	; 2;		; 15NotSame	jsl SetScaleAndMap	; set up the mapping values	lda Rgn,s	sta RgnHandleA	sta RgnHandleC	lda Rgn+2,s	sta RgnHandleA+2	sta RgnHandleC+2	jsr DerefA	lda [RgnPtrA]	; get current region size	cmp #10	bne NotRect;----------------------------------------------------------;; Its a rectangular	region so we'll just map the bounding; box.;	lda RgnPtrA	; LocalMapPoint uses RgnPtrB	sta RgnPtrB	lda RgnPtrA+2	sta RgnPtrB+2	ldy #2	jsr LocalMapPoint	ldy #6	jsr LocalMapPointJDone		; 	jsr UnlockA	jmp BusyEC12NotRect	asl A	; double it, as a guess for the size	clc	adc #4	; for the info stuff	ldx #BufHandle	; offset	jsr GetNewHandle	; get one	bcc T1	pha	; save error code	ldx #RgnHandleA	jsr UnlockHandle	plx	; retrieve error code	jmp BusyErr12* RgnPtrA already holds the region to be mapped, and now RgnPtrC points* to a new buffer, ready to be filled.	PutRgn uses these and expands the* region into a list of inversion points.  It updates PtCount for us.T1	sta BufPtr	; save pointer	stx BufPtr+2	ldy #2	lda #4	sta [BufPtr],y	; initialize buffer	jsl PutRgn	bcc T2	pha	; save error code	ldx #BufHandle	jsr UnlockHandle	; unlock it	Pushlong BufHandle	_DisposeHandle	ldx #RgnHandleA	jsr UnlockHandle	plx	; retrieve error code	jmp BusyErr12T2	ldy #2	lda [BufPtr],y	; get index	sta LastPt	ldy #4	; our current index	sty Counter	; this will be our loop control, tooMapLoop	ldy Counter	; get counter	cpy LastPt	; are we done yet	bpl DoneLoop	sty LastY	lda [BufPtr],y	; get point V	sta MapV	; save on zero page	IncYWd	lda [BufPtr],y	; get point H	sta MapH	; save on zero page	IncYWd	sty Counter	; save y	jsr MapAndScale	; map it	ldy LastY	; get last value back	lda MapV	sta [BufPtr],y	; save V result	IncYWd	lda MapH	sta [BufPtr],y	; save H result	bra MapLoop* When we've finished mapping everything, we have a buffer of inversion* points in BufHandle, and it looks a lot like a CloseRgn call.  We sort* and cull and pack	to put the region back in shape.  PtCount is already* set,DoneLoop	lda LastPt	; current index	lsr A	; divide by 4	lsr A	dea	; subtract status info	sta PtCount	; save it for our friends	jsl SortPoints	jsl CullPoints	jsl PackRgn	ldx #RgnHandleA	jsr UnlockHandle	PushLong BufHandle	_DisposeHandle	bcs ErroutDone	jmp BusyEC12PackError	pha	; save error code	ldx #RgnHandleA	jsr UnlockHandle	PushLong BufHandle	_DisposeHandle	plx	jmp BusyErr12ErrOut	tax	jmp BusyErr12	ENDP****************************************************************** RetrieveRects*****************************************************************	EXPORT RetrieveRectsRetrieveRects	PROC* This local routine locates a FromRect	and ToRect in the stack* and pulls the pointers out onto zero page.ReturnAddress	equ 1OrigDirect	equ ReturnAddress+2RTL1	equ OrigDirect+2RTL2	equ RTL1+3ToRectPtr	equ RTL2+3FromRectPtr	equ ToRectPtr+4	lda FromRectPtr,s	sta Temp	lda FromRectPtr+2,s	sta Temp+2	lda [Temp]	sta FRect	ldy #2	lda [Temp],y	sta FRect+2	ldy #4	lda [Temp],y	sta FRect+4	ldy #6	lda [Temp],y	sta FRect+6	lda ToRectPtr,s	sta Temp	lda ToRectPtr+2,s	sta Temp+2	lda [Temp]	sta TRect	ldy #2	lda [Temp],y	sta TRect+2	ldy #4	lda [Temp],y	sta TRect+4	ldy #6	lda [Temp],y	sta TRect+6	rts	ENDP******************************************************************              SetScaleAndMap*****************************************************************	EXPORT iSetScaleAndMapiSetScaleAndMap	PROC* This local routine uses FRect (FromRect) and TRect (ToRect) on* zero page to set up the parameters for MapPt (so we don't have* to do them more than once for MapRgn,	MapRect, and MapPoly.Top	equ 0Left	equ 2Bottom	equ 4Right	equ 6	sec	lda FRect+Bottom	sbc FRect+Top	sta FHeight	lsr A	; calculate rounding term	sta HeightRound	sec	lda FRect+Right	sbc FRect+Left	sta FWidth	lsr A	; calculate rounding term	sta WidthRound	sec	lda TRect+Bottom	sbc TRect+Top	sta THeight	sec	sbc FHeight	sta DifHeight	sec	lda TRect+Right	sbc TRect+Left	sta TWidth	sec	sbc FWidth	sta DifWidth	rtl	ENDP****************************************************************** MapAndScale*****************************************************************	EXPORT MapAndScaleMapAndScale	PROCTop	equ 0Left	equ 2Bottom	equ 4Right	equ 6	stz Sign	sec	lda MapV	sbc Frect+Top	ldx DifHeight	beq NoVScale	tax	; just to reset flags	bpl NonNeg	eor #$FFFF	; negate it	ina	inc SignNonNeg	pea 0	; space for divide result	pea 0	pea 0	pea 0	pea 0	; space for multiply result	pea 0	pha	PushWord THeight	_Multiply	clc	lda HeightRound	adc 1,s	sta 1,s	lda #0	adc 3,s	sta 3,s	pea 0	; pushlong FHeight	PushWord FHeight	_LongDivide	; whew!	pla	; this is the answer	plx	; if this is <> 0, we're dead anyway	plx	plx	ldx Sign	beq NoVScale	eor #$FFFF	ina	stz SignNoVScale	clc	adc TRect+Top	sta MapV	sec	lda MapH	sbc FRect+Left	ldx DifWidth	beq NoHScale	tax	; just to reset flags	bpl NonNeg2	eor #$FFFF	; negate it	ina	inc SignNonNeg2	pea 0	; space for divide result	pea 0	pea 0	pea 0	pea 0	; space for multiply result	pea 0	pha	PushWord TWidth	_Multiply	; 32 bit result top	of stack (TOS)	clc	lda WidthRound	adc 1,s	sta 1,s	lda #0	adc 3,s	sta 3,s	; we added the rounding to TOS	pea 0	; pushlong FWidth	PushWord FWidth	_LongDivide	; whew!	pla	; this is the answer	plx	; if this is <> 0, we're dead anyway	plx	; discard remainder	plx	ldx Sign	beq NoHScale	eor #$FFFF	inaNoHScale	clc	adc TRect+Left	sta MapH	rts	ENDP****************************************************************** LocalMapPoint*****************************************************************	EXPORT LocalMapPointLocalMapPoint	PROC* The point to be mapped should be in @RgnPtrB with Y pointing* at any offset.	lda [RgnPtrB],y	sta MapV	IncYWd	lda [RgnPtrB],y	sta MapH	phy	jsr MapAndScale	ply	lda MapH	sta [RgnPtrB],y	DecYWd	lda MapV	sta [RgnPtrB],y	rts	ENDP****************************************************************** MapRect*****************************************************************	EXPORT MapRectMapRect	PROC*              using E0VectorsOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3ToRectPtr	equ RTL2+3FromRectPtr	equ ToRectPtr+4DstRect	equ FromRectPtr+4	jsr QDStart	jsr RetrieveRects	jsl SetScaleAndMap	; set up the mapping values	lda DstRect,s	sta RgnPtrB	lda DstRect+2,s	sta RgnPtrB+2	ldy #0	jsr LocalMapPoint	ldy #4	jsr LocalMapPoint	jmp BusyEC12	ENDP****************************************************************** MapPt*****************************************************************	EXPORT MapPtMapPt	PROC*              using E0VectorsOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3ToRectPtr	equ RTL2+3FromRectPtr	equ ToRectPtr+4Point	equ FromRectPtr+4	jsr QDStart	jsr RetrieveRects	jsl SetScaleAndMap	; set up the mapping values	lda Point,s	sta RgnPtrB	lda Point+2,s	sta RgnPtrB+2	ldy #0	jsr LocalMapPoint	jmp BusyEC12	ENDP	END